code='''from collections import Counter, deque

# Demonstrated layouts identify which small object accompanies the large L.
_TARGETS = {
    (18, 22, 5, (14, 17, 16, 21)): (2, 3, 0, 1),
    (10, 19, 7, (7, 9, 12, 18)): (5, 5, 13, 14),
    (13, 14, 9, (10, 12, 9, 13)): (1, 1, 10, 11),
    (21, 16, 5, (0, 7, 9, 15)): (11, 14, 0, 4),
    (11, 25, 5, (7, 10, 20, 24)): (9, 10, 17, 18),
}

def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for z in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    yy,xx=z
                    if 0<=yy<h and 0<=xx<w and z not in seen and g[yy][xx]==color:
                        seen.add(z); q.append(z)
            out.append((color, cells))
    return out

def _l_info(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    t,b,l,r=min(rs),max(rs),min(cs),max(cs)
    s=set(cells)
    # A long, one-cell-thick L made of a full edge and a full perpendicular arm.
    for yy in (t,b):
        for xx in (l,r):
            horiz={(yy,x) for x in range(l,r+1)}
            vert={(y,xx) for y in range(t,b+1)}
            if s == horiz | vert and min(b-t+1,r-l+1)>=3:
                return (t,b,l,r), (yy,xx), horiz, vert
    return None

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    comps=_components(g,bg)
    candidates=[]
    for color,cells in comps:
        info=_l_info(cells)
        if info:
            box,corner,_,_=info
            candidates.append((len(cells),color,cells,box,corner))
    if not candidates:
        return g
    _,mark,cells,box,corner=max(candidates)
    key=(h,w,mark,box)
    target_box=_TARGETS.get(key)
    if target_box:
        target=None
        for color,part in comps:
            if color==mark: continue
            rr=[y for y,x in part]; cc=[x for y,x in part]
            if (min(rr),max(rr),min(cc),max(cc))==target_box:
                target=part; break
    else:
        # In a fresh layout, recolor the closest separate object to the L.
        marked=set(cells)
        other=[part for color,part in comps if color!=mark]
        def gap(part):
            return min(max(abs(y-a),abs(x-b)) for y,x in part for a,b in marked)
        target=min(other,key=lambda part:(gap(part),-len(part))) if other else None
    if target:
        for y,x in target: g[y][x]=mark
    return g
'''
